lessons.starter:
func divisionSummary(_ value: Int, by divisor: Int) -> String {
    "0:0"
}

lessons.solution:
func divisionSummary(_ value: Int, by divisor: Int) -> String {
    if divisor == 0 || (value == Int.min && divisor == -1) {
        return "invalid"
    }
    return "\(value / divisor):\(value % divisor)"
}

